def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Flood-fill zero cells connected to the edge.
    outside = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                stack.append((nr, nc))

    enclosed = {
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] == 0 and (r, c) not in outside
    }

    # Find four-connected components of the 1s. Only components bordering
    # an enclosed region are outlined.
    seen = set()
    qualified = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = set()
            todo = [(r, c)]
            seen.add((r, c))
            while todo:
                x, y = todo.pop()
                comp.add((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        todo.append((nx, ny))

            borders_interior = any(
                (x + dx, y + dy) in enclosed
                for x, y in comp
                for dx in (-1, 0, 1) for dy in (-1, 0, 1)
                if dx or dy
            )
            if borders_interior:
                qualified.update(comp)

    # Mark the inner rim 3 and the outer rim 2.
    for r, c in enclosed:
        if any((r + dr, c + dc) in qualified
               for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
            out[r][c] = 3

    for r, c in qualified:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                        and (nr, nc) in outside):
                    out[nr][nc] = 2

    return out
